def validate(df, schema, baseline):
    errors = schema.check(df)                       # columns, types
    if not 0.7 < len(df) / baseline.rows < 1.3:
        errors.append(f'row count {len(df)} vs {baseline.rows}')
    for col, max_null in schema.max_null_rate.items():
        if df[col].isna().mean() > max_null:
            errors.append(f'{col} null rate too high')
    if not baseline.price_p50 / 2 < df.price.median() < baseline.price_p50 * 2:
        errors.append('price median moved >2x: unit change?')
    if abs(df.label.mean() - baseline.label_rate) > 3 * baseline.label_rate_std:
        errors.append('label rate out of range')
    if errors:
        raise DataValidationError(errors)
